package com.scriptles.cabinet.profile.controller;
import com.scriptles.cabinet.profile.service.ProfileService; import com.scriptles.cabinet.security.AuthenticatedUser; import lombok.RequiredArgsConstructor; import org.springframework.http.ResponseEntity; import org.springframework.security.core.annotation.AuthenticationPrincipal; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/v1/me/following/profiles") @RequiredArgsConstructor public class ProfileFollowController { private final ProfileService profiles; @PutMapping("/{profileId}") public ResponseEntity<Void> follow(@AuthenticationPrincipal AuthenticatedUser viewer,@PathVariable UUID profileId){profiles.follow(viewer.id(),profileId);return ResponseEntity.noContent().build();} @DeleteMapping("/{profileId}") public ResponseEntity<Void> unfollow(@AuthenticationPrincipal AuthenticatedUser viewer,@PathVariable UUID profileId){profiles.unfollow(viewer.id(),profileId);return ResponseEntity.noContent().build();} }
